-- ============================================================================
-- 20260722_exercise_relations.sql — Step 4.4 prerequisite
-- ============================================================================
-- Populates exercise_relations, which 20260719_exercise_catalog_enrichment.sql
-- (4.2a) created but never filled — confirmed live: 0 rows before this
-- migration. Without this, "Alternatives"/"Variations" would have nothing
-- real to query and the detail screen would have to fall back to the same
-- muscle_group filtering already used for the separate "Similar Exercises"
-- bucket, defeating the point of having a dedicated relations table.
--
-- Heuristic (deterministic, no external data, no guessing beyond structured
-- columns already validated this session): only the 760 free-exercise-db
-- rows have reliable target_muscle/category/equipment (see
-- 20260721_exercise_metadata_and_taxonomy.sql), so relations are only
-- generated within that set. Two exercises sharing the same target_muscle
-- and category are related; same equipment too -> 'variation' (a same-tool
-- angle/grip/tempo change), different equipment -> 'alternative' (same
-- muscle and training style, different tool). Capped at 6 per exercise per
-- relation_type, chosen alphabetically by the related exercise's name for
-- reproducibility, to keep the table a reasonable size and each list
-- meaningful in the UI rather than exhaustive. Exercises without both
-- target_muscle and equipment (the omercotkd-gifs/exercisegymgifsdb rows,
-- and the ~65 free-exercise-db rows with no equipment) get no rows here —
-- they still show "Similar Exercises" via the existing muscle_group filter,
-- just not curated Alternatives/Variations.
-- ============================================================================

-- Auto-generated from live exercises data: pairs sharing target_muscle + category,
-- grouped further by equipment match (same equipment -> variation, different -> alternative).
-- Capped at 6 per exercise per relation_type, ordered alphabetically by related
-- exercise name for determinism. 6381 rows total (3046 variation, 3335 alternative).
